-- Reference-led deterministic phenotype taxonomy and per-master artwork requirements.
-- This migration creates no artwork and activates no derived visual asset.
alter table public.horses add column if not exists visual_modifiers jsonb not null default '{"dapple":"none"}'::jsonb;

create table public.equine_visual_taxonomy(category text not null,trait_key text not null,display_name text not null,family text not null default '',sort_order integer not null default 0,metadata jsonb not null default '{}'::jsonb,active boolean not null default true,primary key(category,trait_key),check(category in('face_marking','leg_marking','base_coat','gray_stage','dun','cream','roan','silver','champagne','pearl','dapple','pinto_pattern','leopard_complex','visual_detail','mane','tail','clean_body')));
alter table public.equine_visual_taxonomy enable row level security;
create policy "visual taxonomy is public" on public.equine_visual_taxonomy for select using(active);

